  ? String(body.mode).trim() : 'video';
if (mode !== 'script_only') mode = 'video';
const webhookUrl = (body.webhook_url !== undefined && body.webhook_url !== null && String(body.webhook_url).trim() !== '')
  ? String(body.webhook_url).trim() : null;
function cleanText(raw) {
  let t = String(raw === undefined || raw === null ? '' : raw);
  t = t.replace(/```[\s\S]*?```/g, ' ');
  t = t.replace(/`([^`]*)`/g, '$1');
  t = t.replace(/\*\*([^*]+)\*\*/g, '$1');
  t = t.replace(/__([^_]+)__/g, '$1');
  t = t.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
  t = t.replace(/^#{1,6}\s*/gm, '');
  t = t.replace(/^\s*>\s?/gm, '');
  const lines = t.split('\n').map(function (l) { return l.trim(); }).filter(function (l) {
    if (!l) { return false; }
    if (/^(note:?|tags,|tags:|so i should|just (produce|return|write|output)|the instruction|return only|below is|here is|вот сценарий|верни только|начни ответ|обернув|ok(,|!)?$|хорошо)/i.test(l)) { return false; }
    return true;
  });
  t = lines.join('\n');
  t = t.replace(/^\s*(?:Хук|HOOK|Hook|Основная часть|BODY|Body|Вывод и призыв|Вывод|CTA|Cta|Заключение|Призыв|Концовка|Вступление)\s*[:—–\-]\s*/gim, '');
  t = t.replace(/\s+(?:Хук|Основная часть|Вывод и призыв|Вывод|Заключение|Призыв|Концовка)\s*[:—–\-]\s*/gi, ' ');
  t = t.replace(/\s+(?:HOOK|BODY|CTA)\s*[:—–\-]\s*/gi, ' ');
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}
const cleaned = cleanText(text);
const words = cleaned === '' ? 0 : cleaned.split(/\s+/).length;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
