if (words > MAX_WORDS) {
  const parts = final.split(/(?<=[.!?…])\s+/);
  let acc = '';
  let accWords = 0;
  for (const part of parts) {
    const w = part.split(/\s+/).length;
    if (accWords + w > MAX_WORDS) break;
    acc = acc ? acc + ' ' + part : part;
    accWords += w;
  }
  if (!acc || accWords < Math.max(40, Math.round(MAX_WORDS * 0.6))) {
    acc = final.split(/\s+/).slice(0, MAX_WORDS).join(' ');
    accWords = MAX_WORDS;
  }
  final = acc;
  finalWords = accWords;
}
return [{ json: { ok: true, text: final, words: finalWords, creator: creator, video_length: videoLength, mode: mode, webhook_url: webhookUrl } }];

